INSERT INTO public.dd_service_pricing_rules(service_id,channel_code,pricing_type,base_price_cents,currency,billing_cycle,lock_status,resident_discount_eligible,tax_class,effective_date,status)
SELECT s.id,c.code,CASE WHEN s.sku IN ('DNI-01A-006','DNI-01A-008') THEN 'VARIABLE_QUOTE' ELSE 'FIXED' END,s.base_price_cents,'USD',CASE WHEN s.sku IN ('DNI-01A-006','DNI-01A-008') THEN 'HOURLY' ELSE 'ONETIME' END,'LOCKED',true,'SERVICE',CURRENT_DATE,'ACTIVE' FROM public.services s CROSS JOIN (VALUES ('CH01'),('CH02')) c(code) WHERE s.sku IN ('DNI-01A-001','DNI-01A-002','DNI-01A-003','DNI-01A-004','DNI-01A-005','DNI-01A-006','DNI-01A-007','DNI-01A-008') ON CONFLICT DO NOTHING;